export const PASSAGES: Array<PassageInfo & { length: PassageLength }> =
  [...WORD_RAW, ...RAW].map((p) => {
    const wordCount = countWords(p.text);
    return { ...p, wordCount, length: bucket(wordCount) };
  });

export function pickPassage(
  length: PassageLength,
  excludeId?: string
): PassageInfo {
  let pool = PASSAGES.filter((p) => p.length === length);
  if (pool.length === 0) pool = PASSAGES;
  if (excludeId) {
    const filtered = pool.filter((p) => p.id !== excludeId);
    if (filtered.length > 0) pool = filtered;
  }
  const picked = pool[Math.floor(Math.random() * pool.length)];
  return {
    id: picked.id,
    text: picked.text,
    wordCount: picked.wordCount,
  };
}
